package kr.releasepilot.controlplane.release.api;
import kr.releasepilot.controlplane.analysis.*;import kr.releasepilot.controlplane.release.*;import kr.releasepilot.controlplane.rollout.*;import org.springframework.http.MediaType;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;import tools.jackson.databind.ObjectMapper;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
@RestController @RequestMapping("/api/v1/releases")public class ReleaseEventController{private final ReleaseQueryService access;private final ReleaseRepository releases;private final RolloutExecutionRepository executions;private final RolloutStepRepository steps;private final AnalysisJobRepository analyses;private final ObjectMapper json;public ReleaseEventController(ReleaseQueryService access,ReleaseRepository releases,RolloutExecutionRepository executions,RolloutStepRepository steps,AnalysisJobRepository analyses,ObjectMapper json){this.access=access;this.releases=releases;this.executions=executions;this.steps=steps;this.analyses=analyses;this.json=json;}@GetMapping(value="/{releaseId}/events",produces=MediaType.TEXT_EVENT_STREAM_VALUE)public SseEmitter events(@PathVariable UUID releaseId,Authentication authentication){access.detail(releaseId,authentication);var emitter=new SseEmitter(900_000L);var open=new AtomicBoolean(true);emitter.onCompletion(()->open.set(false));emitter.onTimeout(()->open.set(false));emitter.onError(error->open.set(false));Thread.startVirtualThread(()->stream(releaseId,emitter,open));return emitter;}private void stream(UUID releaseId,SseEmitter emitter,AtomicBoolean open){String previous="";int heartbeat=0;try{while(open.get()){var snapshot=snapshot(releaseId);String current=json.writeValueAsString(snapshot);if(!current.equals(previous)){emitter.send(SseEmitter.event().name("release-state").data(snapshot,MediaType.APPLICATION_JSON));previous=current;}else if(++heartbeat%15==0)emitter.send(SseEmitter.event().comment("keepalive"));Thread.sleep(1000);} }catch(InterruptedException interrupted){Thread.currentThread().interrupt();emitter.complete();}catch(Exception closed){emitter.completeWithError(closed);}}private Snapshot snapshot(UUID releaseId){var release=releases.findById(releaseId).orElseThrow();var execution=executions.findByReleaseId(releaseId);if(execution.isEmpty())return new Snapshot(release.getStatus().name(),List.of(),List.of());var rolloutSteps=steps.findByExecutionIdOrderByStepIndexAsc(execution.get().getId());var jobs=analyses.findByStepIdIn(rolloutSteps.stream().map(RolloutStep::getId).toList());var stepViews=rolloutSteps.stream().map(step->new StepView(step.getStepIndex(),step.getTargetWeight(),step.getStatus().name())).toList();var jobViews=jobs.stream().map(job->new AnalysisView(job.getId(),job.getStatus().name(),job.getVerdict()==null?null:job.getVerdict().name(),job.getReasonCode())).toList();return new Snapshot(release.getStatus().name(),stepViews,jobViews);}record Snapshot(String releaseStatus,List<StepView> steps,List<AnalysisView> analyses){}record StepView(int index,int weight,String status){}record AnalysisView(UUID id,String status,String verdict,String reasonCode){} }
